function applyWorldTransform(){$('#world').style.transform='translate('+S.pan.x+'px,'+S.pan.y+'px) scale('+S.zoom+')';$('#zoomLabel').textContent=Math.round(S.zoom*100)+'%'}
function fitWorkflow(){const ns=S.studio.nodes.filter(n=>S.expanded||n.kind!=='layer');if(!ns.length)return;const minX=Math.min(...ns.map(n=>n.x)),maxX=Math.max(...ns.map(n=>n.x+235)),minY=Math.min(...ns.map(n=>n.y)),maxY=Math.max(...ns.map(n=>n.y+(n.kind==='layer'?42:100))),c=$('#canvas').getBoundingClientRect();S.zoom=Math.min(1,Math.max(.3,Math.min((c.width-100)/(maxX-minX),(c.height-100)/(maxY-minY))));S.pan={x:(c.width-(maxX-minX)*S.zoom)/2-minX*S.zoom,y:(c.height-(maxY-minY)*S.zoom)/2-minY*S.zoom};applyWorldTransform()}
