function renderAssets(){const query=($('#assetSearch')?.value||'').trim().toLowerCase(),known=new Map((S.assets||[]).map(asset=>[asset.path,asset]));projectAssets().forEach(asset=>{if(!known.has(asset))known.set(asset,{path:asset,size:0,kind:'asset',uses:0})});const assets=[...known.values()].filter(asset=>asset.path.toLowerCase().includes(query));$('#assetGrid').innerHTML=assets.map(asset=>{const a=asset.path,image=/[.](png|jpe?g|webp|avif|gif)$/i.test(a),video=/[.](mp4|mov|webm|mkv|m4v)$/i.test(a),audio=/[.](mp3|wav|m4a|aac|ogg|flac)$/i.test(a),font=/[.](ttf|otf|woff2?)$/i.test(a),kind=image?'Image':video?'Video':audio?'Audio':font?'Font':'Asset',uses=asset.uses??0,preview=image?'<img src="/asset/'+a.split('/').map(encodeURIComponent).join('/')+'" alt="">':video?'<video src="/asset/'+a.split('/').map(encodeURIComponent).join('/')+'" muted preload="metadata"></video>':'<div style="aspect-ratio:16/10;display:grid;place-items:center;background:#1a1a1f;font-size:28px">'+(audio?'♪':font?'Aa':'◇')+'</div>',remove=uses===0&&a.startsWith('assets/studio/')?'<div class="asset-actions"><button class="ghost danger" type="button" data-delete-asset="'+esc(a)+'">Delete unused</button></div>':'';return'<article class="asset-card"><button class="asset-open" type="button" data-asset="'+esc(a)+'">'+preview+'<div class="card-body"><div class="card-title">'+esc(a.split('/').pop())+'</div><div class="card-note">'+kind+' · '+uses+' use'+(uses===1?'':'s')+(asset.size?' · '+formatBytes(asset.size):'')+'<br>'+esc(a)+'</div></div></button><button class="ghost" data-inspect-media="'+esc(a)+'">Inspect source</button>'+remove+'</article>'}).join('')||(query?'<div class="empty">No assets match “'+esc(query)+'”.</div>':'<div class="empty">Import local image, video, audio or font assets.</div>');$$('[data-asset]').forEach(card=>card.onclick=()=>{for(const scene of S.project.scenes){const layer=scene.layers.find(item=>item.src===card.dataset.asset||item.fontFile===card.dataset.asset);if(layer){select('layer',layer.id,{sceneId:scene.id});switchView('preview');return}}const audio=S.project.audio.find(item=>item.src===card.dataset.asset);if(audio){select('audio',audio.id);switchView('preview');return}toast('Asset is available but not placed yet.','good','asset-unused')});$$('[data-inspect-media]').forEach(button=>button.onclick=()=>showSourceMetadata(button.dataset.inspectMedia));$$('[data-delete-asset]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{const result=await api('/api/assets',{method:'DELETE',headers:{'content-type':'application/json'},body:JSON.stringify({path:button.dataset.deleteAsset})});S.assets=result.assets;renderAssets();toast('Unused asset deleted')}catch(error){button.disabled=false;toast(error.message,'bad','asset-delete')}})}
function parseColor(value){let hex=String(value||'').trim().replace(/^#/,'');if(!/^(?:[0-9a-f]{3,4}|[0-9a-f]{6}|[0-9a-f]{8})$/i.test(hex))hex='000000';const hasAlpha=hex.length===4||hex.length===8;if(hex.length<=4)hex=hex.split('').map(char=>char+char).join('');return{r:parseInt(hex.slice(0,2),16),g:parseInt(hex.slice(2,4),16),b:parseInt(hex.slice(4,6),16),a:hasAlpha?parseInt(hex.slice(6,8),16)/255:1,hasAlpha}}
function rgbToHsv(r,g,b){r/=255;g/=255;b/=255;const max=Math.max(r,g,b),min=Math.min(r,g,b),delta=max-min;let h=0;if(delta){if(max===r)h=60*((g-b)/delta%6);else if(max===g)h=60*((b-r)/delta+2);else h=60*((r-g)/delta+4)}if(h<0)h+=360;return{h,s:max?delta/max:0,v:max}}
function hsvToRgb(h,s,v){const c=v*s,x=c*(1-Math.abs(h/60%2-1)),m=v-c;let r=0,g=0,b=0;if(h<60){r=c;g=x}else if(h<120){r=x;g=c}else if(h<180){g=c;b=x}else if(h<240){g=x;b=c}else if(h<300){r=x;b=c}else{r=c;b=x}return{r:Math.round((r+m)*255),g:Math.round((g+m)*255),b:Math.round((b+m)*255)}}
function hexByte(value){return Math.max(0,Math.min(255,Math.round(value))).toString(16).padStart(2,'0')}
function pickerHex(state){const rgb=hsvToRgb(state.h,state.s,state.v),alpha=hexByte(state.a*255);return'#'+hexByte(rgb.r)+hexByte(rgb.g)+hexByte(rgb.b)+(state.hasAlpha||state.a<.999?alpha:'')}
let colorPickerState;
function field(label,key,value,type='text',attrs=''){if(type==='color')return'<div class="field"><label>'+label+'</label><div class="color-control"><button class="color-well" type="button" data-color-open="'+esc(key)+'" data-color-value="'+esc(value)+'" aria-label="Choose '+esc(label)+' color"><span class="color-chip" style="background:'+esc(value)+'"></span></button><input class="input" data-field="'+key+'" type="text" value="'+esc(value)+'" spellcheck="false" inputmode="text"></div></div>';const shown=type==='number'&&Number.isFinite(Number(value))?Math.round(Number(value)*10000)/10000:value;return'<div class="field"><label>'+label+'</label><input class="input" data-field="'+key+'" type="'+type+'" value="'+esc(shown)+'" '+attrs+'></div>'}
function paintColorPicker(){if(!colorPickerState)return;const pop=$('#colorPopover'),rgb=hsvToRgb(colorPickerState.h,colorPickerState.s,colorPickerState.v),hex=pickerHex(colorPickerState);pop.querySelector('.color-sv').style.backgroundColor='hsl('+colorPickerState.h+' 100% 50%)';const cursor=pop.querySelector('.color-sv-cursor');cursor.style.left=colorPickerState.s*100+'%';cursor.style.top=(1-colorPickerState.v)*100+'%';pop.querySelector('.color-preview span').style.background=hex;pop.querySelector('.color-range.hue').value=colorPickerState.h;const alpha=pop.querySelector('.color-range.alpha');alpha.value=Math.round(colorPickerState.a*100);alpha.style.setProperty('--alpha-gradient','linear-gradient(90deg,rgba('+rgb.r+','+rgb.g+','+rgb.b+',0),rgb('+rgb.r+','+rgb.g+','+rgb.b+'))');pop.querySelector('[data-color-channel="r"]').value=rgb.r;pop.querySelector('[data-color-channel="g"]').value=rgb.g;pop.querySelector('[data-color-channel="b"]').value=rgb.b;pop.querySelector('[data-color-hex]').value=hex}
function closeColorPicker(){const pop=$('#colorPopover');pop.classList.remove('open');const anchor=colorPickerState?.anchor;colorPickerState=undefined;if(anchor?.isConnected){anchor.classList.remove('open');anchor.focus()};$$('[data-color-open]').forEach(button=>button.classList.remove('open'))}
function renderColorPicker(){const pop=$('#colorPopover');pop.innerHTML='<div class="color-popover-head"><strong>Color</strong><button class="icon-btn" type="button" data-color-close aria-label="Close color picker">'+uiIcon('close')+'</button></div><div class="color-sv"><span class="color-sv-cursor"></span></div><div class="color-slider-row"><div class="color-preview"><span></span></div><input class="color-range hue" type="range" min="0" max="359" step="1" aria-label="Hue"></div><div class="color-slider-row"><span class="tree-sub">Alpha</span><input class="color-range alpha" type="range" min="0" max="100" step="1" aria-label="Alpha"></div><div class="color-values">'+['r','g','b'].map(channel=>'<div class="color-value"><label>'+channel.toUpperCase()+'</label><input type="number" min="0" max="255" data-color-channel="'+channel+'"></div>').join('')+'</div><div class="color-hex-row"><div><label>Hex</label><input data-color-hex spellcheck="false"></div><button class="ghost color-eyedropper" type="button" data-eyedropper aria-label="Pick a color from the screen">'+uiIcon('pipette')+'</button></div><div class="color-actions"><button class="ghost" type="button" data-color-close>Cancel</button><button class="primary" type="button" data-color-apply>Apply</button></div>';paintColorPicker();const sv=pop.querySelector('.color-sv'),updateSv=event=>{const rect=sv.getBoundingClientRect();colorPickerState.s=Math.max(0,Math.min(1,(event.clientX-rect.left)/rect.width));colorPickerState.v=1-Math.max(0,Math.min(1,(event.clientY-rect.top)/rect.height));paintColorPicker()};sv.onpointerdown=event=>{sv.setPointerCapture(event.pointerId);updateSv(event)};sv.onpointermove=event=>{if(sv.hasPointerCapture(event.pointerId))updateSv(event)};pop.querySelector('.color-range.hue').oninput=event=>{colorPickerState.h=Number(event.target.value);paintColorPicker()};pop.querySelector('.color-range.alpha').oninput=event=>{colorPickerState.a=Number(event.target.value)/100;colorPickerState.hasAlpha=true;paintColorPicker()};pop.querySelectorAll('[data-color-channel]').forEach(input=>input.oninput=()=>{const r=Number(pop.querySelector('[data-color-channel="r"]').value),g=Number(pop.querySelector('[data-color-channel="g"]').value),b=Number(pop.querySelector('[data-color-channel="b"]').value),hsv=rgbToHsv(Math.max(0,Math.min(255,r)),Math.max(0,Math.min(255,g)),Math.max(0,Math.min(255,b)));Object.assign(colorPickerState,hsv);paintColorPicker()});pop.querySelector('[data-color-hex]').onchange=event=>{const parsed=parseColor(event.target.value),hsv=rgbToHsv(parsed.r,parsed.g,parsed.b);Object.assign(colorPickerState,hsv,{a:parsed.a,hasAlpha:parsed.hasAlpha});paintColorPicker()};pop.querySelectorAll('[data-color-close]').forEach(button=>button.onclick=closeColorPicker);pop.querySelector('[data-color-apply]').onclick=()=>{const key=colorPickerState.key,value=pickerHex(colorPickerState);const onApply=colorPickerState.onApply;closeColorPicker();if(onApply)onApply(value);else inspectorChange(key,value)};const eye=pop.querySelector('[data-eyedropper]');if(!window.EyeDropper)eye.hidden=true;else eye.onclick=async()=>{try{const result=await new EyeDropper().open(),parsed=parseColor(result.sRGBHex),hsv=rgbToHsv(parsed.r,parsed.g,parsed.b);Object.assign(colorPickerState,hsv);paintColorPicker()}catch{}}}
function openColorPicker(anchor,onApply){(anchor.closest('.modal')||document.body).append($('#colorPopover'));const parsed=parseColor(anchor.dataset.colorValue),hsv=rgbToHsv(parsed.r,parsed.g,parsed.b);colorPickerState={...hsv,a:parsed.a,hasAlpha:parsed.hasAlpha,key:anchor.dataset.colorOpen,onApply,anchor};renderColorPicker();placePopover($('#colorPopover'),anchor);anchor.classList.add('open');$('#colorPopover [data-color-hex]').focus()}
function textfield(label,key,value){return'<div class="field"><label>'+label+'</label><textarea class="textarea" data-field="'+key+'">'+esc(value)+'</textarea></div>'}
function advancedAnimatedEditor(label,property,value){if(typeof value==='number')return field(label,'transform.'+property,value,'number','step="0.01"')+'<button class="pill" data-add-kf="'+property+'">Add keyframes</button><br><br>';return'<div class="field"><label>'+label+' keyframes</label>'+value.keyframes.map((keyframe,index)=>'<div class="keyframe"><div class="keyframe-grid">'+field('Time','transform.'+property+'.keyframes.'+index+'.at',keyframe.at,'number','min="0" step="0.01"')+field('Value','transform.'+property+'.keyframes.'+index+'.value',keyframe.value,'number','step="0.01"')+'<button class="icon-btn danger" data-remove-kf="'+property+':'+index+'" aria-label="Remove keyframe">'+uiIcon('close')+'</button></div>'+easingEditor('Easing','transform.'+property+'.keyframes.'+index+'.ease',keyframe.ease)+'</div>').join('')+'<button class="pill" data-add-kf="'+property+'">'+uiIcon('add')+' Keyframe</button></div>'}
function transformEditor(layer){return'<div class="section-title" style="margin-top:18px"><span>Transform</span></div>'+['x','y','scaleX','scaleY','rotation','opacity','blur'].map(property=>advancedAnimatedEditor(property,property,layer.transform[property])).join('')+'<div class="row">'+field('Anchor X','transform.anchorX',layer.transform.anchorX,'number','min="0" max="1" step="0.01"')+field('Anchor Y','transform.anchorY',layer.transform.anchorY,'number','min="0" max="1" step="0.01"')+'</div>'}
function motionEditor(layer){return'<div class="section-title" style="margin-top:18px"><span>Motion directives</span><button class="icon-btn" id="chooseMotion">＋</button></div>'+layer.motion.map((m,i)=>{const recipe=S.catalog.motions.find(r=>r.id===m.recipe),direction=recipe?.source==='custom'?'':customSelect('Direction','motion.'+i+'.direction',m.direction||'left',['left','right','up','down','in','out']);return'<div class="motion-card"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:9px"><strong>'+esc(m.recipe)+'</strong><button class="icon-btn danger" data-remove-motion="'+i+'">✕</button></div><div class="row">'+field('Start','motion.'+i+'.start',m.start,'number','min="0" step="0.01"')+field('Duration','motion.'+i+'.duration',m.duration,'number','min="0.01" step="0.01"')+'</div><div class="row">'+field('Intensity','motion.'+i+'.intensity',m.intensity,'number','min="0" max="2" step="0.05"')+direction+'</div></div>'}).join('')}
const animationTargets=['sourceFrame','crop.x','crop.y','crop.width','crop.height','border.width','gradientFill','gradientStroke','path','innerRadius','startAngle','endAngle','headSize','turns','x','y','width','height','z','fontSize','letterSpacing','lineHeight','strokeWidth','radius','progress','revealProgress','countProgress','trimStart','playbackRate','volume','color','fill','stroke','background','highlightColor','outlineColor','control1','control2','transform.x','transform.y','transform.scaleX','transform.scaleY','transform.rotation','transform.opacity','transform.blur','shadow.blur','shadow.offsetX','shadow.offsetY','shadow.color','followPath.progress'];
function trackValueField(track,key,value){if(['gradientFill','gradientStroke'].includes(track.target))return jsonField('Gradient keyframe',key,value);if(track.target==='path')return textfield('SVG path',key,value);if(['color','fill','stroke','background','highlightColor','outlineColor','shadow.color'].includes(track.target))return field('Value',key,value,'color');if(['control1','control2'].includes(track.target))return jsonField('Value',key,value);return field('Value',key,value,'number','step="0.01"')}
async function showTrackAnalysis(index){const track=selectedLayer()?.tracks?.[index];if(!track)return;openModal('Velocity and acceleration','<div id="trackAnalysis" role="status">Sampling native animation…</div>');try{const result=await api('/api/track-analysis',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({track,options:{seed:S.project.seed||0,samples:181}})});const target=$('#trackAnalysis');if(!target)return;const colors=['#60a5fa','#f472b6','#a3e635','#fbbf24'];function plot(property,label){const values=result.samples.flatMap(sample=>sample[property]||[]),min=Math.min(0,...values),max=Math.max(0,...values),range=max-min||1;const paths=Array.from({length:result.components},(_,component)=>{let pen=false;const d=result.samples.map((sample,i)=>{const value=sample[property]?.[component];if(value===undefined||value===null){pen=false;return ''}const command=pen?'L':'M';pen=true;return command+(20+i/(result.samples.length-1)*460).toFixed(3)+' '+(130-(value-min)/range*110).toFixed(3)}).join(' ');return '<path d="'+d+'" stroke="'+colors[component]+'" fill="none" stroke-width="2"/>'}).join('');return '<figure><figcaption>'+label+' · '+min.toPrecision(4)+' to '+max.toPrecision(4)+'</figcaption><svg role="img" aria-label="'+label+'" viewBox="0 0 500 150" style="width:100%;background:#111827;border-radius:8px"><path d="M20 20V130H480" fill="none" stroke="#64748b"/>'+paths+'</svg></figure>'}target.innerHTML='<p>'+esc(result.target)+' · '+result.components+' component(s). Blue / pink / green / amber follow component order. Time: '+result.samples[0].time+'–'+result.samples.at(-1).time+' seconds.</p>'+plot('value','Value')+plot('velocity','Velocity (units/s)')+plot('acceleration','Acceleration (units/s²)')+'<p>Gaps mark keyframe or cycle boundaries where derivatives may be undefined. Numerical step: '+result.step+' seconds.</p>'}catch(error){const target=$('#trackAnalysis');if(target)target.textContent=error.message}}
function trackGroupEditor(layer){return heading('Track groups')+(layer.trackGroups||[]).map((group,index)=>'<div class="motion-card" data-track-group-card="'+index+'">'+field('Group ID','trackGroups.'+index+'.id',group.id)+checkboxField('Mute group','trackGroups.'+index+'.muted',group.muted)+checkboxField('Solo group','trackGroups.'+index+'.solo',group.solo)+checkboxField('Lock group','trackGroups.'+index+'.locked',group.locked)+'<button class="ghost" data-remove-track-group="'+index+'">Remove group</button></div>').join('')+'<button class="ghost" id="addTrackGroup">Add track group</button>'}
function propertyLinkEditor(layer){const scene=S.project.scenes.find(item=>item.id===S.selected.sceneId),sources=(scene?.layers||[]).filter(item=>item.id!==layer.id).map(item=>item.id);return heading('Property links')+(layer.propertyLinks||[]).map((link,index)=>'<div class="motion-card">'+checkboxField('Link enabled','propertyLinks.'+index+'.enabled',link.enabled)+customSelect('Destination property','propertyLinks.'+index+'.target',link.target,animationTargets)+customSelect('Source layer','propertyLinks.'+index+'.sourceLayerId',link.sourceLayerId,sources)+customSelect('Source property','propertyLinks.'+index+'.sourceProperty',link.sourceProperty,animationTargets)+field('Scale','propertyLinks.'+index+'.scale',link.scale,'number','step="0.1"')+field('Offset','propertyLinks.'+index+'.offset',link.offset,'number','step="0.1"')+'<button class="ghost" data-remove-property-link="'+index+'">Remove link</button></div>').join('')+'<button class="ghost" id="addPropertyLink" '+(!sources.length?'disabled':'')+'>Add property link</button>'}
function fullTrackEditor(layer){return trackGroupEditor(layer)+propertyLinkEditor(layer)+'<div class="section-title" style="margin-top:18px"><span>Direct animation tracks</span><button class="icon-btn" id="addTrack" aria-label="Add animation track">'+uiIcon('add')+'</button></div>'+(layer.tracks||[]).map((track,index)=>'<div class="motion-card" data-track-card="'+index+'"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:9px"><strong>'+esc(track.id)+'</strong><button class="icon-btn danger" data-remove-track="'+index+'" aria-label="Remove '+esc(track.id)+'">'+uiIcon('close')+'</button></div>'+'<button class="ghost" data-track-analysis="'+index+'">Velocity and acceleration</button>'+field('Track ID','tracks.'+index+'.id',track.id)+checkboxField('Enabled','tracks.'+index+'.enabled',track.enabled)+checkboxField('Solo','tracks.'+index+'.solo',track.solo)+checkboxField('Locked','tracks.'+index+'.locked',track.locked)+customSelect('Group','tracks.'+index+'.group',track.group||'none',['none',...(layer.trackGroups||[]).map(group=>group.id)])+customSelect('Target','tracks.'+index+'.target',track.target,animationTargets)+customSelect('Interpolation','tracks.'+index+'.interpolation',track.interpolation||'linear',['linear','shortest-angle','discrete','path'])+customSelect('Operation','tracks.'+index+'.operation',track.operation,['replace','add','multiply'])+customSelect('Default extrapolation','tracks.'+index+'.extrapolate',track.extrapolate,['clamp','extend','wrap','identity','loop','ping-pong'])+'<div class="row">'+customSelect('Before first key','tracks.'+index+'.extrapolateLeft',track.extrapolateLeft||track.extrapolate,['clamp','extend','wrap','identity','loop','ping-pong'])+customSelect('After last key','tracks.'+index+'.extrapolateRight',track.extrapolateRight||track.extrapolate,['clamp','extend','wrap','identity','loop','ping-pong'])+'</div>'+optionalObject('Procedural noise','tracks.'+index+'.noise',track.noise,{seed:0,amplitude:8,frequency:1,octaves:2,lacunarity:2,gain:.5},track.noise?'<div class="row">'+field('Seed','tracks.'+index+'.noise.seed',track.noise.seed,'number','step="1"')+field('Amplitude','tracks.'+index+'.noise.amplitude',track.noise.amplitude,'number','min="0.001" step="0.1"')+field('Frequency','tracks.'+index+'.noise.frequency',track.noise.frequency,'number','min="0.001" step="0.1"')+field('Octaves','tracks.'+index+'.noise.octaves',track.noise.octaves,'number','min="1" max="8" step="1"')+'</div>':'')+track.keyframes.map((keyframe,keyframeIndex)=>'<div class="keyframe"><div class="keyframe-grid">'+field('Time','tracks.'+index+'.keyframes.'+keyframeIndex+'.at',keyframe.at,'number','min="0" step="0.01"')+trackValueField(track,'tracks.'+index+'.keyframes.'+keyframeIndex+'.value',keyframe.value)+'<button class="icon-btn danger" data-remove-track-keyframe="'+index+':'+keyframeIndex+'" aria-label="Remove keyframe">'+uiIcon('close')+'</button></div>'+checkboxField('Hold until next keyframe','tracks.'+index+'.keyframes.'+keyframeIndex+'.hold',keyframe.hold||false)+easingEditor('Easing','tracks.'+index+'.keyframes.'+keyframeIndex+'.ease',keyframe.ease)+'</div>').join('')+'<button class="pill" data-add-track-keyframe="'+index+'">'+uiIcon('add')+' Keyframe</button></div>').join('')}
