function geometryAnchorsInspector(project){const anchors=project.anchors||[];return heading('Geometry anchors')+(anchors.length?anchors.map((anchor,index)=>'<div class="motion-card"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:9px"><strong>'+esc(anchor.id)+'</strong><button class="icon-btn danger" data-remove-anchor="'+index+'" aria-label="Remove '+esc(anchor.id)+'">'+uiIcon('close')+'</button></div>'+field('Anchor ID','anchors.'+index+'.id',anchor.id)+'<div class="row">'+field('X','anchors.'+index+'.x',anchor.x,'number','step="0.01"')+field('Y','anchors.'+index+'.y',anchor.y,'number','step="0.01"')+'</div></div>').join(''):'<div class="tree-sub" style="margin-bottom:10px">Add a shared point for connectors and focal markers.</div>')+'<button class="pill" id="addGeometryAnchor">'+uiIcon('add')+' Anchor</button>'}
function geometryAnchorUses(id){return S.project.scenes.reduce((count,scene)=>count+scene.layers.filter(layer=>layer.startAnchor===id||layer.endAnchor===id||layer.centerAnchor===id).length,0)}
function addGeometryAnchor(){snapshot();const ids=new Set((S.project.anchors||[]).map(anchor=>anchor.id));let suffix=1,id='anchor-'+suffix;while(ids.has(id))id='anchor-'+(++suffix);S.project.anchors.push({id,x:Math.round(projectMetric('width')/2),y:Math.round(projectMetric('height')/2)});saveProject();renderInspector()}
function removeGeometryAnchor(index){const anchor=S.project.anchors?.[index];if(!anchor)return;const uses=geometryAnchorUses(anchor.id);if(uses){toast(anchor.id+' is used by '+uses+' layer'+(uses===1?'':'s')+'. Remove those bindings first.','bad','anchor-in-use');return}snapshot();S.project.anchors.splice(index,1);saveProject();renderInspector()}
document.addEventListener('click',event=>{const add=event.target.closest?.('#addGeometryAnchor'),remove=event.target.closest?.('[data-remove-anchor]');if(add){event.preventDefault();addGeometryAnchor()}else if(remove){event.preventDefault();removeGeometryAnchor(Number(remove.dataset.removeAnchor))}})
