function parameterControls(){let group='';function control(p,key,value){if(p.derive)return '<div class="field"><label>'+esc(p.label)+' (derived)</label><output class="input">'+esc(JSON.stringify(S.renderSpec?.parameterValues?.[p.id]??value))+'</output></div>';const label=esc(p.label),description=p.description?'<div class="tree-sub">'+esc(p.description)+'</div>':'';if(value===null)return jsonField(p.label+' (optional)',key,null)+description;let html;if(p.type==='boolean')html=checkboxField(p.label,key,value);else if(p.type==='enum')html='<div class="field"><label>'+label+'</label><select class="input" data-field="'+esc(key)+'">'+(p.options||[]).map(option=>'<option value="'+esc(option)+'" '+(option===value?'selected':'')+'>'+esc(option)+'</option>').join('')+'</select></div>';else if(p.type==='object')html='<fieldset><legend>'+label+'</legend>'+Object.entries(p.properties||{}).map(([id,child])=>control(child,key+'.'+id,value?.[id]??child.default)).join('')+'</fieldset>';else if(p.type==='array')html=jsonField(p.label,key,value);else if(['number','dimension','duration'].includes(p.type))html=field(label,key,value,'number',(p.min!==undefined?'min="'+p.min+'" ':'')+(p.max!==undefined?'max="'+p.max+'" ':'')+'step="'+(p.step??(p.type==='dimension'?1:'any'))+'"');else html=field(label,key,value,p.type==='color'?'color':'text',(p.minLength!==undefined?'minlength="'+p.minLength+'" ':'')+(p.maxLength!==undefined?'maxlength="'+p.maxLength+'"':''));return html+description}return(S.project.parameters||[]).map(p=>{const title=p.group&&p.group!==group?heading(esc(p.group)):'';group=p.group||'';const frozen=(S.project.dataSources||[]).find(source=>source.parameterId===p.id);return title+control(p,'parameterValues.'+p.id,Object.hasOwn(S.project.parameterValues||{},p.id)?S.project.parameterValues[p.id]:frozen?frozen.value:p.default)}).join('')}
