function transitionInspector(prefix,label,transition){const presentation=transition.presentation||transition.type,timing=transition.timing||transition.ease;return heading(label)+customSelect('Presentation',prefix+'.presentation',presentation,['cut','crossfade','slide-left','slide-right','push-up','zoom','blur','wipe-left','wipe-right','iris','slide-up','slide-down','wipe-up','wipe-down','clock','flip','cube','door'])+customSelect('Mode',prefix+'.mode',transition.mode||'symmetric',['symmetric','incoming','outgoing'])+(transition.overlayCompositionId?field('Overlay composition',prefix+'.overlayCompositionId',transition.overlayCompositionId):'')+field('Duration',prefix+'.duration',transition.duration,'number','min="0" max="3" step="0.01"')+easingEditor('Timing',prefix+'.timing',timing)}
